import glob, json, os

for tfile in glob.glob(r"C:\Users\JOSE\.gemini\antigravity\brain\*\.system_generated\logs\transcript_full*.jsonl"):
    with open(tfile, "r", encoding="utf-8", errors="ignore") as f:
        for idx, line in enumerate(f):
            if "modalEditarFactura" in line and "tabla-solicitudes" in line:
                obj = json.loads(line)
                txt = json.dumps(obj)
                # check if this line contains view_file output with line numbers
                if "Showing lines" in txt and "admin_diesel.html" in txt:
                    print(f"File {tfile} line {idx} has view_file output!")
                    # let's save the json
                    with open(f"view_diesel_{idx}.json", "w", encoding="utf-8") as out:
                        out.write(txt)
